/**
 * Returns the caller's revenue workspace mapping and preflight health, creating the local-mode workspace on first touch.
 * @summary Get current revenue workspace
 */
export const GetRevenueWorkspace200Response = zod
  .strictObject({
    id: zod.uuid().describe("Stable UUID primary key."),
    lastVerifiedAt: zod.iso
      .datetime({ offset: true })
      .nullish()
      .describe("When the link was last verified."),
    mode: zod.enum(["local", "linked"]).describe("Workspace mode."),
    outboundOrganizationId: zod.string().optional().describe("OutboundConsole organization id."),
    outboundWorkspaceId: zod.string().optional().describe("OutboundConsole workspace id."),
    preflightAvailable: zod
      .boolean()
      .describe("Whether policy preflight can run (linked and active)."),
    status: zod
      .enum(["active", "disconnected", "repair_required"])
      .describe(
        "Lifecycle\/status slug. Subscription rows use billing states; background task runs use queued\/running\/succeeded\/failed\/stopped.",
      ),
  })
  .describe(
    "Mapping between the Rowboat tenant and the canonical OutboundConsole workspace. Local mode has no link: observation and draft-only execution work while preflight and sends stay disabled.",
  );

